import{c as s,Q as i,j as a,m as o}from"./chunks/framework.CdiUUa3G.js";const u=JSON.parse('{"title":"Docker stack — local serving + on-demand pipelines","description":"","frontmatter":{},"headers":[],"relativePath":"guides/docker-stack.md","filePath":"guides/docker-stack.md"}'),t={name:"guides/docker-stack.md"};function n(r,e,d,l,c,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="docker-stack-—-local-serving-on-demand-pipelines" tabindex="-1">Docker stack — local serving + on-demand pipelines <a class="header-anchor" href="#docker-stack-—-local-serving-on-demand-pipelines" aria-label="Permalink to &quot;Docker stack — local serving + on-demand pipelines&quot;">​</a></h1><p>The <code>docker-compose.yml</code> at repo root brings up a production-shape nginx that serves the static SvelteKit bundle, plus an on-demand pipeline runner that executes any <code>tsx scripts/&lt;name&gt;.ts</code> inside a container with the full Node + system-gdal stack baked in. Per <strong><a href="./../rfc/RFC-024">RFC-024</a></strong> the stack is <em>local</em> + <em>CI</em>; VPS deploy + GHCR publishing are deferred to a future RFC. <strong>GH Pages remains the canonical production site.</strong></p><p>The docker stack lets you (a) exercise the production-shape nginx-served bundle locally — cache headers, MIME types, SPA fallback — exactly the way the future VPS will serve it, (b) run heavy pipelines like <code>fetch:launches</code> or <code>images:hotspots</code> without needing system gdal on your laptop, and (c) trust a CI gate (<code>.github/workflows/docker-e2e.yml</code>) that the same stack works in a runner.</p><hr><h2 id="first-time-setup" tabindex="-1">First-time setup <a class="header-anchor" href="#first-time-setup" aria-label="Permalink to &quot;First-time setup&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # if you haven&#39;t already — pulls package-lock.json deps</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # produces ./build — the nginx container bind-mounts this</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:up</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # docker compose up -d web — pulls nginx:alpine on first run (~5 s)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">open</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # the site, served by nginx, on port 8080</span></span></code></pre></div><p><code>docker compose up</code> starts only the <code>web</code> service. The <code>pipeline-runner</code> service is gated behind <code>profiles: [&#39;manual&#39;]</code> and only spawns when you explicitly invoke <code>docker compose run --rm pipeline-runner …</code> (or one of the <code>npm run docker:*</code> wrappers below).</p><p>If you skip <code>npm run build</code>, the web container will start but every request returns 404 because there&#39;s nothing to serve — the bind-mount points at an empty directory. The compose file does not auto-build because (a) <code>npm run build</code> is a host concern (it runs vite which expects host-side <code>node_modules</code>) and (b) it&#39;s the same step you already run for GH Pages, so wiring it inside the docker bring-up would duplicate the contract.</p><hr><h2 id="tearing-down" tabindex="-1">Tearing down <a class="header-anchor" href="#tearing-down" aria-label="Permalink to &quot;Tearing down&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:down</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # stop + remove containers, keep volumes</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # also wipe orrery-cache (image-cache for pipelines)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:reset-data</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # alias: removes the named volumes — next up re-creates them</span></span></code></pre></div><p><code>docker compose down</code> keeps the orrery-cache volume so the next pipeline invocation doesn&#39;t have to re-download HiRISE JP2s, the GCAT TSV, etc. Use <code>-v</code> (or <code>npm run docker:reset-data</code>) when you specifically want a cold first-run state.</p><hr><h2 id="running-pipelines-on-demand" tabindex="-1">Running pipelines on-demand <a class="header-anchor" href="#running-pipelines-on-demand" aria-label="Permalink to &quot;Running pipelines on-demand&quot;">​</a></h2><p>Every <code>npm run …</code> data pipeline has a <code>npm run docker:…</code> mirror that runs the same script inside the pipeline-runner container:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:fetch-launches</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # scripts/fetch-launches.ts — refreshes launches.json</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:images:hotspots</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # scripts/fetch-hotspot-imagery.ts — Mars/Moon orbital imagery</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:fetch-assets</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # scripts/fetch-assets.ts — agency imagery + cache</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:validate-data</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # scripts/validate-data.ts — ajv schema validation</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:build-image-provenance</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # scripts/build-image-provenance.ts</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:build-link-provenance</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # scripts/build-link-provenance.ts</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:audit-launches</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # scripts/audit-report-launches.ts — emits HTML report</span></span></code></pre></div><p>The first invocation in a fresh checkout triggers a <strong>one-time pipeline-runner image build</strong> (~10-15 min on Apple Silicon — Node 20 base + apt install gdal-dev + build-essential + <code>npm ci</code> with <code>gdal-async</code> source-compile against system gdal). Final image is ~3.4 GB. Subsequent invocations re-use the cached layers and start in ~2-3 seconds. Source code is bind-mounted at runtime (read-only), so script edits don&#39;t require a rebuild.</p><p>You can pass arguments through:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pipeline-runner</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/fetch-launches.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2026-05-01</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pipeline-runner</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/audit-report-launches.ts</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/audit.html</span></span></code></pre></div><p>Pipeline writes land in <code>./static/data</code> on the host (bind-mount). The web container&#39;s <code>/data/*</code> path is overlay-mounted at that same host directory, so a fresh <code>launches.json</code> shows up at <code>http://localhost:8080/data/launches.json</code> on the next request — no rebuild, no restart. The PWA service worker&#39;s <code>NetworkFirst</code> strategy (<code>vite.config.ts:90</code>) handles client-side freshness.</p><hr><h2 id="what-s-where" tabindex="-1">What&#39;s where <a class="header-anchor" href="#what-s-where" aria-label="Permalink to &quot;What&#39;s where&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.</span></span>\n<span class="line"><span>├── Dockerfile                       — pipeline-runner only. Web uses stock nginx:alpine.</span></span>\n<span class="line"><span>├── docker-compose.yml               — two services: web + pipeline-runner (manual profile)</span></span>\n<span class="line"><span>├── .dockerignore                    — keeps the pipeline build context lean</span></span>\n<span class="line"><span>├── ops/docker/nginx.conf            — cache headers, SPA fallback, gzip, mime types</span></span>\n<span class="line"><span>├── docs/guides/docker-stack.md      — this file</span></span>\n<span class="line"><span>└── .github/workflows/docker-e2e.yml — CI gate, Playwright against the live stack</span></span></code></pre></div><p>Volumes:</p><ul><li><code>orrery-cache</code> (named docker volume) — pipeline-side <code>.image-cache/</code> reuse across invocations.</li><li>Anonymous volume on <code>/repo/node_modules</code> (pipeline-runner only) — masks the host repo bind-mount so the image&#39;s linux-arm64 <code>node_modules</code> wins over your darwin-arm64 one. Without it, <code>esbuild</code> / <code>sharp</code> / <code>gdal-async</code> would try to load the wrong-platform binaries inside the linux container.</li><li><code>./build</code>, <code>./static/data</code>, <code>./ops/docker/nginx.conf</code> (bind-mounts) — host paths the web container reads.</li></ul><p>The web container itself has no Dockerfile and no persistent volume — it&#39;s stock <code>nginx:alpine</code> (25 MB image) with three read-only bind-mounts. Easy to reason about, fast to start.</p><hr><h2 id="the-env-file" tabindex="-1">The <code>.env</code> file <a class="header-anchor" href="#the-env-file" aria-label="Permalink to &quot;The `.env` file&quot;">​</a></h2><p>Some pipelines accept secrets. Create <code>.env</code> at repo root (gitignored):</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LL2_PATREON_KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=lk_xxx        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># optional Launch Library 2 Patreon tier key</span></span></code></pre></div><p><code>docker-compose</code> reads <code>.env</code> automatically and threads the values into the pipeline-runner container&#39;s environment. The web container doesn&#39;t read any secrets.</p><p>CI sets these directly via <code>${‌{ secrets.LL2_PATREON_KEY }}</code> in <code>docker-e2e.yml</code>; the <code>.env</code> file is local-only.</p><hr><h2 id="ci-—-the-docker-e2e-gate" tabindex="-1">CI — the docker-e2e gate <a class="header-anchor" href="#ci-—-the-docker-e2e-gate" aria-label="Permalink to &quot;CI — the docker-e2e gate&quot;">​</a></h2><p><code>.github/workflows/docker-e2e.yml</code> runs on every push to <code>main</code> and on PRs that touch the docker surface (<code>Dockerfile</code>, <code>docker-compose.yml</code>, <code>ops/docker/**</code>, <code>package-lock.json</code>, <code>playwright.config.ts</code>, or the workflow itself). It:</p><ol><li>Runs <code>npm ci &amp;&amp; npm run build</code> on the runner.</li><li>Brings up <code>docker compose up -d web</code>.</li><li>Curl-polls <code>http://localhost:8080/</code> until healthy (max 120s).</li><li>Smoke-tests the critical paths (root, sub-route, <code>/data/launches.json</code> with <code>Cache-Control: no-cache</code> and <code>Content-Type: application/json</code>).</li><li>Runs the <strong>desktop-chromium</strong> Playwright project with <code>PLAYWRIGHT_BASE_URL=http://localhost:8080</code>.</li><li>Uploads <code>playwright-report/</code> + dumps <code>docker compose logs web</code> on failure.</li></ol><p>Mobile-chromium is <strong>not</strong> covered here — that suite runs in <code>e2e.yml</code> against <code>vite preview</code>. The two workflows partition the test surface: <code>e2e.yml</code> exercises the SvelteKit + Vite artefact; <code>docker-e2e.yml</code> exercises the production-shape nginx-served bundle. A red <code>docker-e2e.yml</code> means <em>the docker stack regressed</em> (cache headers, SPA fallback, mime types, volume mount) — a specific signal, easy to attribute.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="bind-for-0-0-0-0-8080-failed-port-is-already-allocated" tabindex="-1"><code>Bind for 0.0.0.0:8080 failed: port is already allocated</code> <a class="header-anchor" href="#bind-for-0-0-0-0-8080-failed-port-is-already-allocated" aria-label="Permalink to &quot;`Bind for 0.0.0.0:8080 failed: port is already allocated`&quot;">​</a></h3><p>Something else is on <code>:8080</code>. Find it (<code>lsof -i :8080</code>) and stop it, or temporarily edit the port mapping in <code>docker-compose.yml</code> (<code>&#39;8080:80&#39;</code> → <code>&#39;8081:80&#39;</code>) and use <code>http://localhost:8081</code> for that session.</p><h3 id="web-container-starts-but-every-request-404s" tabindex="-1">Web container starts but every request 404s <a class="header-anchor" href="#web-container-starts-but-every-request-404s" aria-label="Permalink to &quot;Web container starts but every request 404s&quot;">​</a></h3><p><code>./build</code> doesn&#39;t exist. Run <code>npm run build</code> on the host first, then <code>docker compose restart web</code>.</p><h3 id="_404-not-found-for-missions-but-missions-works" tabindex="-1"><code>404 Not Found</code> for <code>/missions/</code> but <code>/missions</code> works <a class="header-anchor" href="#_404-not-found-for-missions-but-missions-works" aria-label="Permalink to &quot;`404 Not Found` for `/missions/` but `/missions` works&quot;">​</a></h3><p>That was a real bug we fixed early in Slice 1 — adapter-static emits <code>build/missions.html</code> (file at root) rather than <code>build/missions/index.html</code>. <code>ops/docker/nginx.conf</code> is configured to try <code>$uri.html</code> before falling through to <code>/index.html</code>. If you see it again, your nginx.conf may have drifted.</p><h3 id="pipeline-image-build-fails-on-libgdal-dev" tabindex="-1">Pipeline image build fails on <code>libgdal-dev</code> <a class="header-anchor" href="#pipeline-image-build-fails-on-libgdal-dev" aria-label="Permalink to &quot;Pipeline image build fails on `libgdal-dev`&quot;">​</a></h3><p>The pipeline-runner Dockerfile installs system gdal via <code>apt-get install libgdal-dev</code>. If that fails, the apt mirror may be transiently unavailable. Re-run; if it fails again, check <code>https://www.debian.org/mirror/list</code> and your network. macOS hosts running Docker Desktop don&#39;t need host-side gdal — that&#39;s the whole point of the pipeline-runner image.</p><h3 id="pipeline-image-build-fails-with-gyp-err-not-found-make" tabindex="-1">Pipeline image build fails with <code>gyp ERR! not found: make</code> <a class="header-anchor" href="#pipeline-image-build-fails-with-gyp-err-not-found-make" aria-label="Permalink to &quot;Pipeline image build fails with `gyp ERR! not found: make`&quot;">​</a></h3><p>Means <code>node-pre-gyp</code> couldn&#39;t find a prebuilt <code>gdal-async</code> binary for your <code>node-vXXX-linux-arm64</code> ABI (returns 404 on the GH releases CDN) and fell back to source compile, but <code>build-essential</code> is missing from the image. The shipped Dockerfile installs <code>build-essential</code> + <code>python3</code> alongside <code>libgdal-dev</code>; if you derived a slimmer image and dropped them, add them back.</p><p>Expect the first pipeline build to take 10-15 min on Apple Silicon — most of that is the <code>gdal-async</code> source-compile against system gdal. The image is ~3.4 GB once built; subsequent invocations reuse the cached layers and start in seconds.</p><h3 id="error-transformerror-you-installed-esbuild-for-another-platform" tabindex="-1"><code>Error [TransformError]: You installed esbuild for another platform</code> <a class="header-anchor" href="#error-transformerror-you-installed-esbuild-for-another-platform" aria-label="Permalink to &quot;`Error [TransformError]: You installed esbuild for another platform`&quot;">​</a></h3><p>The host&#39;s <code>node_modules</code> (darwin-arm64) is bleeding into the linux-arm64 container through the <code>:/repo</code> bind-mount, and esbuild loads the wrong-platform native binary. <code>docker-compose.yml</code> mounts an anonymous volume on <code>/repo/node_modules</code> specifically to mask this — if you see this error, that volume is missing. Don&#39;t delete the line <code>- /repo/node_modules</code> from the <code>pipeline-runner</code> volumes section. Same root cause applies to <code>sharp</code>, <code>canvas</code>, and <code>gdal-async</code> if you ever see those crash on platform-binary loading.</p><h3 id="pipeline-writes-don-t-show-up-on-8080" tabindex="-1">Pipeline writes don&#39;t show up on <code>:8080</code> <a class="header-anchor" href="#pipeline-writes-don-t-show-up-on-8080" aria-label="Permalink to &quot;Pipeline writes don&#39;t show up on `:8080`&quot;">​</a></h3><p>The bind-mount points at <code>./static/data</code> on the host. If you wrote to <code>./build/data</code> instead (which adapter-static populates <em>at build time</em>), the web container won&#39;t see it because that path is masked by the static-data overlay. Always write through the pipeline-runner (which mounts <code>./static/data:/repo/static/data</code> read-write) — that path is correct by construction.</p><h3 id="docker-desktop-holds-8-gb-of-ram-even-when-idle" tabindex="-1">Docker Desktop holds ~8 GB of RAM even when idle <a class="header-anchor" href="#docker-desktop-holds-8-gb-of-ram-even-when-idle" aria-label="Permalink to &quot;Docker Desktop holds ~8 GB of RAM even when idle&quot;">​</a></h3><p>That&#39;s the Apple Virtualization Framework VM that hosts the Linux docker engine on macOS. The default reservation is 8 GB; you can lower it via <em>Docker Desktop → Settings → Resources → Memory</em>. 4 GB is usually enough for this stack.</p><h3 id="build-context-1-gb" tabindex="-1">Build context &gt; 1 GB <a class="header-anchor" href="#build-context-1-gb" aria-label="Permalink to &quot;Build context &gt; 1 GB&quot;">​</a></h3><p>Should be impossible with the current <code>.dockerignore</code>, which excludes <code>node_modules</code>, <code>.svelte-kit</code>, <code>build</code>, <code>test-results</code>, <code>.image-cache</code>, <code>.linux-node-modules</code>, <code>.xdg-cache</code>, <code>.xdg-data</code>. If you see &quot;transferring context: XGB&quot; in <code>docker compose build</code> output, run <code>du -h -d 2 . | sort -h | tail -20</code> to find the leak and add it to <code>.dockerignore</code>.</p><h3 id="macos-bind-mount-permission-errors-inside-the-pipeline-container" tabindex="-1">macOS bind-mount permission errors inside the pipeline container <a class="header-anchor" href="#macos-bind-mount-permission-errors-inside-the-pipeline-container" aria-label="Permalink to &quot;macOS bind-mount permission errors inside the pipeline container&quot;">​</a></h3><p>The pipeline-runner runs as root inside the container. Docker Desktop on macOS uses <code>virtiofs</code> for bind-mounts, which usually handles ownership transparently. If you see <code>EACCES</code> on host paths, restart Docker Desktop — its virtiofs daemon sometimes drifts after long uptime.</p><hr><h2 id="future-work-not-in-this-guide" tabindex="-1">Future work (not in this guide) <a class="header-anchor" href="#future-work-not-in-this-guide" aria-label="Permalink to &quot;Future work (not in this guide)&quot;">​</a></h2><p>These are spelled out in RFC-024 §10. None are implemented today:</p><ul><li>GHCR publishing pipeline (push images to <code>ghcr.io/&lt;owner&gt;/orrery</code> on merge to main).</li><li>VPS host configuration (Caddy reverse proxy + Let&#39;s Encrypt + watchtower).</li><li>Scheduled pipelines on the VPS (replace <code>refresh-launches.yml</code> GH Actions cron with <code>systemd.timer</code>).</li><li>Production hardening (non-root user, read-only rootfs, distroless base).</li><li>Multi-arch builds (<code>linux/arm64</code> if the VPS choice ends up arm-based).</li></ul><p>Each will become its own RFC + ADR set when the user prioritises it.</p><hr><p><em>Orrery · docs/guides/docker-stack.md · 2026-05-22 — Slice 3 of RFC-024 implementation</em></p>',67)])])}const k=s(t,[["render",n]]);export{u as __pageData,k as default};
